// Готовит сообщение для Telegram (дамп в чат) и для email (тред в info@).
// Payload (см. internal/support/service.go): {message_id, from_email,
// from_name, topic, message, source_url, user_id?}.
const raw = $input.first().json;
const e = raw.body || raw;
const d = e.data || {};

const esc = (s) => String(s ?? '').replace(/([_*`])/g, '\\$1');
const topics = { payment: '💸 Оплата', bug: '🐛 Баг', feature: '✨ Идея', other: '❓ Другое' };
const topic = topics[d.topic] || `❓ ${esc(d.topic || 'other')}`;
const from = d.from_name
  ? `${esc(d.from_name)} (${esc(d.from_email)})`
  : esc(d.from_email || '—');
const src = d.source_url ? `\n🔗 ${esc(d.source_url)}` : '';
const auth = d.user_id ? ` · uid=\`${String(d.user_id).slice(0,8)}\`` : ' · гость';

const tgText = `📨 *Поддержка: ${topic}*${auth}\n\n` +
               `*От:* ${from}\n\n` +
               `${esc(d.message || '')}` +
               src;

const emailSubject = `[Поддержка/${d.topic || 'other'}] от ${d.from_email || 'guest'}`;
const emailText = `Тип: ${d.topic}\n` +
                  `От: ${d.from_name ? d.from_name + ' <' + d.from_email + '>' : d.from_email}\n` +
                  `User: ${d.user_id || 'гость'}\n` +
                  `Страница: ${d.source_url || '—'}\n\n` +
                  `${d.message || ''}`;
const emailHtml = `<p><strong>Тип:</strong> ${d.topic}</p>` +
                  `<p><strong>От:</strong> ${d.from_name ? d.from_name + ' &lt;' + d.from_email + '&gt;' : d.from_email}</p>` +
                  `<p><strong>User:</strong> ${d.user_id || 'гость'}</p>` +
                  `<p><strong>Страница:</strong> ${d.source_url || '—'}</p>` +
                  `<hr>` +
                  `<p>${String(d.message || '').replace(/\n/g,'<br>')}</p>`;

return [{ json: {
  tgText,
  emailSubject, emailText, emailHtml,
  replyTo: d.from_email || ''
}}];
